sys_script_include.script:
var VendorRiskUtils = Class.create();
VendorRiskUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

	calculateRiskScore: function (vendorSysId) {
		var gr = new GlideRecordSecure('x_cdltd_vendor_o_0_vendor_request');
		if (gr.get(vendorSysId)) {
			var totalScore = 0;

			if (gr.country.restricted) {
				totalScore += 40;
			}

			if (gr.annual_contract_value > 5000000) {
				totalScore += 20;
			}

			if (gr.category === '4') {
				totalScore += 10;
			}

			var documentGr = new GlideRecordSecure('x_cdltd_vendor_o_0_vendor_document');
			documentGr.addQuery('vendor_request', vendorSysId);
			documentGr.addQuery('received', false);
			documentGr.query();

			var penalty = 0;
			while (documentGr.next() && penalty < 30) {
				penalty += 10;
			}
			totalScore += penalty;

			var riskLevel = "High";
			if (totalScore < 30) {
				riskLevel = "Low";
			} else if (totalScore < 60) {
				riskLevel = "Medium";
			}

			return {
				riskScore: totalScore,
				riskLevel: riskLevel
			};
		}

	},

	isDuplicateTaxId: function() {
		var taxId = this.getParameter('sysparm_tax_id');

		var gr = new GlideRecordSecure('x_cdltd_vendor_o_0_vendor_request');
		gr.addQuery('state', '!=', 5);
		gr.addQuery('state', '!=', 6);
		gr.addQuery('tax_id', taxId);
		gr.query();

		if (gr.hasNext()) {
			return 'true';
		}

		return 'false';
	},

    type: 'VendorRiskUtils'
});
